    sources:[...centralBarbarossaCanonSources,{href:"../extrapolatedWWIIDevelopments.md",label:"Extrapolated WWII Developments — controlling August 1941 campaign framework"},centralBarbarossaArchiveSource,centralBarbarossaArmyHistory,centralBarbarossaHolocaustSource,{href:"https://commons.wikimedia.org/wiki/File:Befehlshaber_Panzergruppe.svg",label:"Wikimedia Commons — 1941 panzer-group command flag"}],
    categories:["Panzer Group 2","German armored formations","Army Group Center","Operation Barbarossa","German–Soviet War"],
